228	        Owner owner = this.clinicService.findOwnerById(ownerId);
229	        if (owner == null) {
230	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
231	        }
232	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
233	    }
234	
235	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
236	    @Override
237	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
238	        String idempotencyKey = currentIdempotencyKey();
239	        OwnerDto replayed = replayIfSeen(idempotencyKey);
240	        if (replayed != null) {
241	            return new ResponseEntity<>(replayed, HttpStatus.OK);
242	        }
243	        validateRequiredFields(ownerFieldsDto);
244	        HttpHeaders headers = new HttpHeaders();
245	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
246	        rejectFutureRegistrationDate(owner.getRegistrationDate());
247	        LocalDate registrationDate = Owner.resolveRegistrationDate(owner.getRegistrationDate());
248	        owner.setRegistrationDate(registrationDate);
249	        requireDailyCapacity(registrationDate);
250	        long cityOwnerCount = countOwnersInCity(owner.getCity());
251	        requireCityHasCapacity(owner.getCity(), cityOwnerCount);
252	        owner.setCapacityWarning(isApproachingCityCapacity(cityOwnerCount));
253	        validatePostcode(owner);
254	        applyAddress(owner, ownerFieldsDto);
255	        owner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
256	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
257	        owner.setHouseholdId(computeHouseholdId(owner.getLastName(), owner.getPostcode()));
258	        boolean declaredHouseholdMember = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
259	        requireUniqueIdentity(owner);
260	        flagPossibleDuplicate(owner, declaredHouseholdMember);
261	        owner.setMemberId(deduplicateMemberId(owner.buildMemberId()));
262	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
263	        stampHouseholdSize(owner);
264	        capMembershipLevelToHousehold(owner);
265	        owner.setBulkSignupWarning(countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD);
266	        this.clinicService.saveOwner(owner);
267	        rememberCreate(idempotencyKey, owner);
268	        AUDIT.info("Owner created: id={} memberId={} registrationDate={} membershipLevel={}",
269	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(), owner.getMembershipLevel());
270	        emitOwnerCreatedEvent(owner);
271	        enqueueWelcomeNotification(owner);
272	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
273	        headers.setLocation(UriComponentsBuilder.newInstance()
274	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
275	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
276	    }
277	
278	    /**
279	     * Emits the immutable structured {@code OWNER_CREATED} event to the {@link #AUDIT} logger as a
280	     * compact JSON object, alongside the human-readable audit line. The event's {@code seq} is drawn
281	     * from the process-wide {@link #AUDIT_SEQUENCE}, so it strictly increases across creates, and it
282	     * carries both the owner's id and its current primary identifier via
283	     * {@link #primaryIdentifier(Owner)}.
284	     *
285	     * @param owner the owner that was just created and saved
286	     */
287	    private void emitOwnerCreatedEvent(Owner owner) {
288	        OwnerCreatedEvent event = new OwnerCreatedEvent(AUDIT_SEQUENCE.incrementAndGet(),
289	            owner.getId(), owner.getMemberId(), owner.getMembershipLevel());
290	        AUDIT.info(event.toJson());
291	    }
292	
293	    /**
294	     * Enqueues a welcome notification for a just-created owner by emitting a single line to the
295	     * {@link #NOTIFY} logger carrying the owner's id and its member id.
296	     *
297	     * @param owner the owner that was just created and saved
298	     */
299	    private void enqueueWelcomeNotification(Owner owner) {
300	        NOTIFY.info("Welcome owner: id={} memberId={}", owner.getId(), owner.getMemberId());
301	    }
302	
303	    /**
304	     * The immutable structured event emitted on a successful owner create. {@code seq} is the
305	     * process-wide monotonically increasing sequence across creates; {@code ownerId} is the new
306	     * owner's id; {@code memberId} carries the owner's unified member id; {@code membershipLevel} is
307	     * the owner's membership level. It serializes to a compact JSON object whose {@code event} is
308	     * always {@value #EVENT_TYPE}.
309	     *
310	     * @param seq the monotonically increasing create sequence number
311	     * @param ownerId the created owner's id
312	     * @param memberId the owner's unified member id
313	     * @param membershipLevel the owner's membership level
314	     */
315	    private record OwnerCreatedEvent(int seq, Integer ownerId, String memberId, Integer membershipLevel) {
316	
317	        /** The fixed {@code event} discriminator carried by every emitted event. */
318	        private static final String EVENT_TYPE = "OWNER_CREATED";
319	
320	        /** Shared, thread-safe mapper used only to serialize the event to its JSON form. */
321	        private static final ObjectMapper MAPPER = JsonMapper.builder().build();
322	
323	        /**
324	         * Serializes this event to its compact JSON form
325	         * {@code {seq, ownerId, memberId, membershipLevel, event}}, with the fields in that order.
326	         *
327	         * @return the event as a JSON object string
328	         */
329	        private String toJson() {
330	            Map<String, Object> fields = new LinkedHashMap<>();
331	            fields.put("seq", this.seq);
332	            fields.put("ownerId", this.ownerId);
333	            fields.put("memberId", this.memberId);
334	            fields.put("membershipLevel", this.membershipLevel);
335	            fields.put("event", EVENT_TYPE);
336	            return MAPPER.writeValueAsString(fields);
337	        }
338	    }
339	
340	    /**
341	     * Reads the client-supplied idempotency key from the current request's {@code Idempotency-Key}
342	     * header. Returns {@code null} when the header is absent or blank (the create is not idempotent),
343	     * or when no servlet request is bound to the current thread.
344	     *
345	     * <p>The header is read from the bound request rather than taken as a {@code @RequestHeader} method
346	     * parameter because {@code addOwner}'s signature is fixed by the generated {@link OwnersApi}
347	     * interface and cannot carry an extra parameter.
348	     *
349	     * @return the trimmed idempotency key, or {@code null} when none was supplied
350	     */
351	    private String currentIdempotencyKey() {
352	        if (RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attributes) {
353	            String key = attributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
354	            if (StringUtils.hasText(key)) {
355	                return key.trim();
356	            }
357	        }
358	        return null;
359	    }
360	
361	    /**
362	     * Returns the owner originally created under the given idempotency key, so a create repeating a
363	     * key already seen replays the first result instead of creating a duplicate. Yields {@code null}
364	     * when there is no key, the key has not been seen, or the remembered owner no longer exists (in
365	     * which case the create proceeds normally).
366	     *
367	     * @param idempotencyKey the client-supplied idempotency key, or {@code null} when none was supplied
368	     * @return the originally created owner as a DTO, or {@code null} when there is nothing to replay
369	     */
370	    private OwnerDto replayIfSeen(String idempotencyKey) {
371	        if (idempotencyKey == null) {
372	            return null;
373	        }
374	        Integer existingId = idempotentCreates.get(idempotencyKey);
375	        if (existingId == null) {
376	            return null;
377	        }
378	        Owner existing = this.clinicService.findOwnerById(existingId);
379	        return existing == null ? null : ownerMapper.toOwnerDto(existing);
380	    }
381	
382	    /**
383	     * Remembers the id of a just-created owner against the idempotency key that produced it, so a later
384	     * create repeating the same key can be replayed by {@link #replayIfSeen}. A {@code null} key (the
385	     * create was not idempotent) is ignored.
386	     *
387	     * @param idempotencyKey the client-supplied idempotency key, or {@code null} when none was supplied
388	     * @param owner the owner that was just created and saved
389	     */
390	    private void rememberCreate(String idempotencyKey, Owner owner) {
391	        if (idempotencyKey != null) {
392	            idempotentCreates.put(idempotencyKey, owner.getId());
393	        }
394	    }
395	
396	    /**
397	     * Rejects a create whose supplied registration date is later than the server's current date. A
398	     * registration may be back-dated but never post-dated, so a future date is treated as a client
399	     * error. A {@code null} supplied date (the client omitted it) is allowed, as it defaults to the
400	     * server date.
401	     *
402	     * @param suppliedRegistrationDate the registration date from the request, or {@code null} when the
403	     *     client omitted it
404	     * @throws FutureRegistrationDateException if the supplied date is after the server's current date
405	     */
406	    private void rejectFutureRegistrationDate(LocalDate suppliedRegistrationDate) {
407	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
408	            throw new FutureRegistrationDateException(suppliedRegistrationDate);
409	        }
410	    }
411	
412	    /**
413	     * Rejects a create once {@value #MAX_OWNERS_PER_DAY} or more owners already carry the new owner's
414	     * adjusted business-day registration date. Existing owners are counted by {@code registrationDate}
415	     * equal to that date, before the new owner is saved, so the count reflects only the owners that
416	     * existed prior to this create.
417	     *
418	     * @param registrationDate the new owner's effective registration date, already rolled forward onto
419	     *     a business day
420	     * @throws DailyOwnerLimitException if {@value #MAX_OWNERS_PER_DAY} or more owners are already
421	     *     registered on that business day
422	     */
423	    private void requireDailyCapacity(LocalDate registrationDate) {
424	        if (countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
425	            throw new DailyOwnerLimitException(registrationDate);
426	        }
427	    }
428	
429	    /**
430	     * Counts the existing owners whose registration date equals the given business-day date. This is
431	     * evaluated before the new owner is saved, so it reflects only the owners that existed prior to
432	     * this create. It is the single definition of the per-day count shared by the daily-limit rule and
433	     * the bulk-signup warning.
434	     *
435	     * @param registrationDate the effective business-day registration date to count against
436	     * @return the number of pre-existing owners registered on that date
