577	     * @param telephone the raw telephone value from the request
578	     * @return the normalized E.164 telephone number
579	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
580	     */
581	    private String normalizeTelephone(String telephone) {
582	        String e164 = toE164(telephone);
