589	    /**
590	     * Converts a telephone value to E.164 form, giving the single authoritative definition of a
591	     * telephone's normalized form. Spaces, dashes and brackets are stripped. A leading {@code '+'}
592	     * and its country code are kept when present; otherwise country code {@code '+61'} is assumed and
593	     * a single leading {@code '0'} is dropped from the national digits. The result is valid only when
594	     * it contains 8 to 15 digits after the {@code '+'} and, for a recognized country code (see
595	     * {@link #NATIONAL_NUMBER_LENGTH}), carries exactly that country's required national-number length.
596	     *
597	     * <p>Returns {@code null} rather than throwing when the value cannot form a valid E.164 number, so
598	     * it is safe to apply to already-stored (possibly legacy) values when comparing them.
599	     *
600	     * @param telephone the raw telephone value, possibly {@code null}
601	     * @return the E.164 string, or {@code null} if the value cannot form a valid E.164 number
602	     */
603	    private String toE164(String telephone) {
604	        if (telephone == null) {
605	            return null;
606	        }
607	        String cleaned = telephone.replaceAll("[ \\-()]", "");
608	        String digits;
609	        if (cleaned.startsWith("+")) {
610	            digits = cleaned.substring(1);
611	        } else {
612	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
613	            digits = "61" + national;
614	        }
615	        if (!digits.matches("[0-9]{8,15}")) {
616	            return null;
617	        }
618	        if (!nationalNumberLengthValid(digits)) {
619	            return null;
620	        }
621	        return "+" + digits;
622	    }
623	
624	    /**
625	     * Checks a normalized E.164 digit string (country code followed by national digits, without the
626	     * leading {@code '+'}) against the per-country national-number length rule. For a country code
627	     * listed in {@link #NATIONAL_NUMBER_LENGTH} the national part must have exactly the required length
628	     * (e.g. {@code '+61'} needs 9 national digits, {@code '+1'} needs 10); any other country code is
629	     * accepted, leaving only the generic total-length rule to apply.
630	     *
631	     * @param digits the E.164 digits without the leading {@code '+'}
632	     * @return {@code true} if the national-number length matches the country code's requirement
633	     */
634	    private boolean nationalNumberLengthValid(String digits) {
635	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTH.entrySet()) {
636	            String code = entry.getKey();
637	            if (digits.startsWith(code)) {
638	                return digits.length() - code.length() == entry.getValue();
639	            }
640	        }
641	        return true;
642	    }
