644	    /**
645	     * Normalizes an optional owner email. An absent (null or blank) email is allowed and yields
646	     * {@code null}. When present, the value must be a syntactically valid address whose domain is not
647	     * on the disposable-domain blocklist ({@link #DISPOSABLE_EMAIL_DOMAINS}); it is then stored and
648	     * returned lower-cased.
649	     *
650	     * @param email the raw email value from the request, possibly {@code null}
651	     * @return the lower-cased email, or {@code null} when none was supplied
652	     * @throws InvalidOwnerFieldsException if a value is present but is not a valid email address or
653	     *     its domain is on the disposable-domain blocklist
654	     */
655	    private String normalizeEmail(String email) {
656	        if (!StringUtils.hasText(email)) {
657	            return null;
658	        }
659	        String trimmed = email.trim();
660	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
661	            throw new InvalidOwnerFieldsException(List.of("email"));
662	        }
663	        String normalized = trimmed.toLowerCase(Locale.ROOT);
664	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
665	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
