671	    /**
672	     * Rejects an owner whose whole identity key is already used by an existing (non-deleted) owner.
673	     * This is the single consolidated duplicate check: the identity key
674	     * ({@link Owner#getIdentityKey()}) is the lower-case SHA-256 hex of the owner's normalized
675	     * telephone, lower-cased email (empty when absent) and the Soundex of its last name joined with
676	     * {@code '|'}, and a create is a duplicate only when the new owner's whole key equals an existing
677	     * owner's. Because the telephone is part of the key, two owners sharing a last name and postcode
678	     * but carrying different telephones have different identity keys and are both allowed (the second
679	     * is flagged a soft match by {@link #flagPossibleDuplicate}). Owners flagged deleted are ignored.
680	     *
681	     * @param owner the owner being created, with its normalized telephone, email and last name set
682	     * @throws DuplicateIdentityException if another owner already has this identity key
683	     */
684	    private void requireUniqueIdentity(Owner owner) {
685	        String identityKey = owner.getIdentityKey();
686	        boolean inUse = this.clinicService.findAllOwners().stream()
687	            .filter(existing -> !existing.isDeleted())
688	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
689	        if (inUse) {
