694	    /**
695	     * De-duplicates a newly computed member id against the ids already held by existing owners. When
696	     * the computed id is unique it is returned unchanged. When it collides with an existing owner's
697	     * {@code memberId}, {@code '-<n>'} is appended with the smallest {@code n} of 2 or more that makes
698	     * the result unique (so a second collision yields {@code '-2'}, a third {@code '-3'}, and so on),
699	     * and that de-duplicated id is returned.
700	     *
701	     * @param memberId the freshly computed member id to de-duplicate
702	     * @return a member id not held by any existing owner
703	     */
704	    private String deduplicateMemberId(String memberId) {
705	        Set<String> inUse = this.clinicService.findAllOwners().stream()
706	            .map(Owner::getMemberId)
707	            .filter(Objects::nonNull)
708	            .collect(Collectors.toSet());
709	        if (!inUse.contains(memberId)) {
710	            return memberId;
711	        }
712	        int n = 2;
713	        String candidate;
714	        do {
715	            candidate = memberId + "-" + n;
716	            n++;
717	        } while (inUse.contains(candidate));
718	        return candidate;
719	    }
