721	    /**
722	     * Flags the owner being created as a possible (soft) duplicate of an existing owner. A soft match is
723	     * not a hard duplicate (its identity key is unique, already enforced by {@link #requireUniqueIdentity})
724	     * but it shares an existing owner's last-name {@linkplain Soundex#encode(String) Soundex} and postcode
725	     * (both present and equal) while carrying a different identity key. When such an existing owner is
726	     * found the created owner is flagged ({@code possibleDuplicate} true) with {@code possibleDuplicateOf}
727	     * set to that owner's id; the lowest matching id is used when several owners match. Otherwise the flag
728	     * is false and {@code possibleDuplicateOf} is left unset.
729	     *
730	     * <p>A declared household member (one created with {@code sharesHousehold}) is never a suspected
731	     * duplicate: it has deliberately opted in to sharing its household, so the flag is forced false.
732	     *
733	     * @param owner the owner being created, with its normalized telephone, email, last name and postcode set
734	     * @param declaredHouseholdMember whether the owner opted in to its household via {@code sharesHousehold}
735	     */
736	    private void flagPossibleDuplicate(Owner owner, boolean declaredHouseholdMember) {
737	        if (declaredHouseholdMember || owner.getPostcode() == null) {
738	            owner.setPossibleDuplicate(false);
739	            return;
740	        }
741	        String identityKey = owner.getIdentityKey();
742	        String soundex = Soundex.encode(owner.getLastName());
743	        Integer matchId = this.clinicService.findAllOwners().stream()
744	            .filter(existing -> soundex.equals(Soundex.encode(existing.getLastName()))
745	                && owner.getPostcode().equals(existing.getPostcode())
746	                && !identityKey.equals(existing.getIdentityKey()))
747	            .map(Owner::getId)
748	            .min(Integer::compareTo)
749	            .orElse(null);
750	        owner.setPossibleDuplicate(matchId != null);
751	        owner.setPossibleDuplicateOf(matchId);
752	    }
