789	    /**
790	     * Caps the new owner's membership level so it cannot exceed one above the current maximum
791	     * membership level among the existing members of its household - the non-deleted owners that share
792	     * the deterministic {@code householdId}. The new owner's level is lowered to that ceiling only when
793	     * its derived level sits above it; otherwise it is left to be derived normally. When the household
794	     * has no existing member no cap applies and the level is left untouched.
795	     *
796	     * @param owner the owner being created, with its deterministic {@code householdId} and
797	     *     {@code householdSize} already set
798	     */
799	    private void capMembershipLevelToHousehold(Owner owner) {
800	        OptionalInt maxMemberLevel = householdMembers(owner).stream()
801	            .filter(existing -> !existing.isDeleted())
802	            .mapToInt(Owner::getMembershipLevel)
803	            .max();
804	        if (maxMemberLevel.isEmpty()) {
805	            return;
806	        }
807	        int cap = maxMemberLevel.getAsInt() + 1;
808	        if (owner.getMembershipLevel() > cap) {
809	            owner.setMembershipLevel(cap);
