813	    /**
814	     * Computes the deterministic, shared household identifier for a last name and postcode: the first
815	     * 12 upper-case hexadecimal characters (the first 6 bytes) of the SHA-256 digest of
816	     * {@code normalizedLastName + '|' + postcode}. The last name is normalized (case-insensitive,
817	     * whitespace-collapsed) and an absent postcode contributes an empty string, so every owner that
818	     * shares a last name and postcode computes the same identifier and therefore the same household.
819	     *
820	     * @param lastName the last name of the household
821	     * @param postcode the postcode of the household, possibly {@code null}
822	     * @return the 12-character upper-case hex household identifier
823	     */
824	    private String computeHouseholdId(String lastName, String postcode) {
825	        String key = normalizeForHousehold(lastName) + "|" + (postcode == null ? "" : postcode);
826	        try {
827	            byte[] digest = MessageDigest.getInstance("SHA-256")
828	                .digest(key.getBytes(StandardCharsets.UTF_8));
829	            StringBuilder hex = new StringBuilder(12);
830	            for (int i = 0; i < 6; i++) {
831	                hex.append(String.format("%02X", digest[i]));
832	            }
833	            return hex.toString();
834	        } catch (NoSuchAlgorithmException e) {
835	            throw new IllegalStateException("SHA-256 algorithm not available", e);
836	        }
837	    }
