852	     * Trims leading and trailing whitespace and collapses any internal run of whitespace to a single
853	     * space, giving the single definition of that step shared by the owner normalizers. A {@code null}
854	     * value yields an empty string.
855	     *
856	     * @param value the raw value, possibly {@code null}
857	     * @return the trimmed, whitespace-collapsed value
858	     */
859	    private String collapseWhitespace(String value) {
860	        if (value == null) {
861	            return "";
862	        }
863	        return value.trim().replaceAll("\\s+", " ");
864	    }
