866	    /**
867	     * Normalizes an owner's address to its canonical, stored-and-returned form: leading and trailing
868	     * whitespace is trimmed, any internal run of whitespace is collapsed to a single space, the result
869	     * is upper-cased, and common street-type abbreviations are expanded as whole words
870	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} or
871	     * blank-after-collapsing value normalizes to an empty string. The transformation is idempotent, so
872	     * applying it to an already-normalized (or legacy) value is safe when comparing addresses.
873	     *
874	     * @param address the raw address value, possibly {@code null}
875	     * @return the normalized address
876	     */
877	    private String normalizeAddress(String address) {
878	        String collapsed = collapseWhitespace(address).toUpperCase(Locale.ROOT);
879	        if (collapsed.isEmpty()) {
880	            return "";
881	        }
882	        String[] tokens = collapsed.split(" ");
883	        StringBuilder normalized = new StringBuilder();
884	        for (int i = 0; i < tokens.length; i++) {
885	            if (i > 0) {
886	                normalized.append(' ');
887	            }
888	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
889	        }
890	        return normalized.toString();
891	    }
