893	    /**
894	     * Applies the owner's address from the request, preferring the structured form over the flat one.
895	     * When a non-blank {@code addressLine1} is supplied it is normalized ({@link #normalizeAddress}) and
896	     * stored, along with the normalized {@code addressLine2} when present, and the stored {@code address}
897	     * is the composed string ({@link #composeAddress}). Otherwise the flat {@code address} input is
898	     * normalized and stored, and the structured lines are cleared. Normalization therefore applies to
899	     * whichever address fields are supplied, and everything that reads {@link Owner#getAddress()} sees
900	     * the structured address when present, falling back to the flat address.
901	     *
902	     * @param owner the owner being created
903	     * @param ownerFieldsDto the submitted owner fields
904	     */
905	    private void applyAddress(Owner owner, OwnerFieldsDto ownerFieldsDto) {
906	        String line1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
907	        if (StringUtils.hasText(line1)) {
908	            String line2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
909	            String normalizedLine2 = StringUtils.hasText(line2) ? line2 : null;
910	            owner.setAddressLine1(line1);
911	            owner.setAddressLine2(normalizedLine2);
912	            owner.setAddress(composeAddress(line1, normalizedLine2));
913	        } else {
914	            owner.setAddressLine1(null);
915	            owner.setAddressLine2(null);
916	            owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
917	        }
918	    }
