920	    /**
921	     * Composes the stored-and-returned {@code address} string from the normalized structured lines: the
922	     * normalized {@code addressLine1}, with a single space and the normalized {@code addressLine2}
923	     * appended when the second line is present.
924	     *
925	     * @param line1 the normalized first address line
926	     * @param line2 the normalized second address line, or {@code null} when absent
927	     * @return the composed address string
928	     */
929	    private String composeAddress(String line1, String line2) {
930	        return line2 == null ? line1 : line1 + " " + line2;
931	    }
