33	/**
34	 * Simple JavaBean domain object representing an owner.
35	 *
36	 * @author Ken Krebs
37	 * @author Juergen Hoeller
38	 * @author Sam Brannen
39	 * @author Michael Isvy
40	 */
41	@Entity
42	@Table(name = "owners")
43	public class Owner extends Person {
44	    @Column(name = "title")
45	    private String title;
46	
47	    @Column(name = "address")
48	    @NotEmpty
49	    private String address;
50	
51	    @Column(name = "address_line1")
52	    private String addressLine1;
53	
54	    @Column(name = "address_line2")
55	    private String addressLine2;
56	
57	    @Column(name = "city")
58	    @NotEmpty
59	    private String city;
60	
61	    @Column(name = "telephone")
62	    @NotEmpty
63	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form (a '+' followed by 8 to 15 digits)")
64	    private String telephone;
65	
66	    @Column(name = "email")
67	    private String email;
68	
69	    @Column(name = "registration_date", columnDefinition = "DATE")
70	    private LocalDate registrationDate;
71	
72	    @Column(name = "birth_date", columnDefinition = "DATE")
73	    private LocalDate birthDate;
74	
75	    @Column(name = "member_id")
76	    private String memberId;
77	
78	    @Column(name = "household_id")
79	    private String householdId;
80	
81	    @Column(name = "namesake_count")
82	    private Integer namesakeCount;
83	
84	    @Column(name = "household_size")
85	    private Integer householdSize;
86	
87	    @Column(name = "postcode")
88	    private String postcode;
89	
90	    @Column(name = "bulk_signup_warning")
91	    private Boolean bulkSignupWarning;
92	
93	    @Column(name = "capacity_warning")
94	    private Boolean capacityWarning;
95	
96	    @Column(name = "possible_duplicate")
97	    private Boolean possibleDuplicate;
98	
99	    @Column(name = "possible_duplicate_of")
100	    private Integer possibleDuplicateOf;
101	
102	    @Column(name = "membership_level")
103	    private Integer membershipLevel;
104	
105	    @Column(name = "deleted", nullable = false)
106	    private boolean deleted = false;
107	
108	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
109	    private Set<Pet> pets;
110	
111	    /**
112	     * Fixed city-to-region table used to derive {@link #getLocality() locality} when the postcode
113	     * is absent or in no known range. Any city not listed derives the locality {@code 'UNKNOWN'}.
114	     */
115	    private static final Map<String, String> CITY_REGION = Map.of(
116	        "Sydney", "NSW",
117	        "Melbourne", "VIC",
118	        "Brisbane", "QLD");
119	
120	    /**
121	     * Inclusive 4-digit postcode range per region, used to derive {@link #getLocality() locality}
122	     * from the postcode in preference to the city: NSW 2000-2099, VIC 3000-3099, QLD 4000-4099.
123	     */
