343	    /**
344	     * The fiscal year a date falls in, as a full calendar year. The fiscal year starts on 1 July and
345	     * is named by the calendar year in which it ends: a date in July through December belongs to the
346	     * next calendar year's fiscal year, while January through June stays in the current one.
347	     *
348	     * @param date the date to classify
349	     * @return the fiscal year as a four-digit calendar year
350	     */
351	    private static int fiscalYearOf(LocalDate date) {
352	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
353	    }
