491	    /**
492	     * The leading region component of a {@link #getMemberId() member id}: its leading run of letters,
493	     * which ends at the first fiscal-year digit. The member id has no separators, so the region is the
494	     * alphabetic prefix (e.g. {@code 'NSW'} or {@code 'UNKNOWN'}) that precedes the {@code <FY>} digits.
495	     *
496	     * @param memberId the member id to read the region from
497	     * @return the leading region string
498	     */
499	    private static String leadingRegion(String memberId) {
500	        int end = 0;
501	        while (end < memberId.length() && Character.isLetter(memberId.charAt(end))) {
502	            end++;
503	        }
504	        return memberId.substring(0, end);
505	    }
