519	    /**
520	     * The owner's segment, formatted {@code '<TIER>_<AREA>'}, one of {@code 'PREMIUM_METRO'},
521	     * {@code 'PREMIUM_REGIONAL'}, {@code 'STANDARD_METRO'} or {@code 'STANDARD_REGIONAL'}. {@code TIER}
522	     * is {@code 'PREMIUM'} when the {@link #getMembershipLevel() membership level} is 3 or more,
523	     * otherwise {@code 'STANDARD'}. {@code AREA} is {@code 'METRO'} when the {@link #getLocality()
524	     * locality} is a known region (NSW, VIC or QLD), otherwise {@code 'REGIONAL'}.
525	     *
526	     * @return the owner segment string
527	     */
528	    public String getOwnerSegment() {
529	        String tier = getMembershipLevel() >= 3 ? "PREMIUM" : "STANDARD";
530	        String area = REGION_TIMEZONE.containsKey(getLocality()) ? "METRO" : "REGIONAL";
531	        return tier + "_" + area;
532	    }
