551	    /**
552	     * Builds this owner's member id, formatted {@code '<REGION><FY><HASH8><CHK>'}. {@code REGION} is
553	     * the region derived from the postcode (falling back to the city, then {@code 'UNKNOWN'}; see
554	     * {@link #deriveRegion()}); {@code FY} is the two-digit fiscal year of the
555	     * {@link #getRegistrationDate() registration date} (the fiscal year starts on 1 July; see
556	     * {@link #fiscalYearOf(LocalDate)}); {@code HASH8} is the first 8 upper-case hexadecimal
557	     * characters of the SHA-256 digest of the owner's normalized telephone concatenated with its last
558	     * name (the same hash the region-and-hash identity uses); and {@code CHK} is a single Luhn check
559	     * digit over the digits of the {@code <REGION><FY><HASH8>} prefix (e.g. {@code 'NSW261A2B3C4D7'}).
560	     * It carries no sequence number, so it is a pure function of the owner's region, fiscal year,
561	     * telephone and last name. Call this once at create time and store the result via
562	     * {@link #setMemberId(String)}, which thereafter backs {@link #getLocality()} and
563	     * {@link #getFiscalYear()}.
564	     *
565	     * @return the assembled member id
566	     */
567	    public String buildMemberId() {
568	        String base = deriveRegion()
569	            + String.format("%02d", fiscalYearOf(this.registrationDate) % 100)
570	            + sha256Hex8(this.telephone + this.getLastName());
571	        return base + luhnCheckDigit(base);
572	    }
