574	    /**
575	     * Computes the first 8 upper-case hexadecimal characters (the first 4 bytes) of the SHA-256 digest
576	     * of the given value's UTF-8 bytes, the {@code HASH8} component of the customer code.
577	     *
578	     * @param value the value to hash
579	     * @return the 8-character upper-case hex prefix of the SHA-256 digest
580	     */
581	    private static String sha256Hex8(String value) {
582	        try {
583	            byte[] digest = MessageDigest.getInstance("SHA-256")
584	                .digest(value.getBytes(StandardCharsets.UTF_8));
585	            StringBuilder hex = new StringBuilder(8);
586	            for (int i = 0; i < 4; i++) {
587	                hex.append(String.format("%02X", digest[i]));
588	            }
589	            return hex.toString();
590	        }
591	        catch (NoSuchAlgorithmException e) {
592	            throw new IllegalStateException("SHA-256 algorithm not available", e);
593	        }
594	    }
