622	    /**
623	     * The owner's preferred contact channel, derived from the owner's details. Returns
624	     * {@code 'EMAIL'} when an email address is present, otherwise {@code 'PHONE'}.
625	     *
626	     * @return {@code 'EMAIL'} when an email address is present, otherwise {@code 'PHONE'}
627	     */
628	    public String getContactPreference() {
629	        boolean hasEmail = this.email != null && !this.email.isBlank();
630	        return hasEmail ? "EMAIL" : "PHONE";
631	    }
