695	        this.householdSize = householdSize;
696	    }
697	
698	    public String getPostcode() {
699	        return this.postcode;
700	    }
701	
702	    public void setPostcode(String postcode) {
703	        this.postcode = postcode;
704	    }
705	
706	    public Boolean getBulkSignupWarning() {
707	        return this.bulkSignupWarning;
708	    }
709	
