715	        return this.capacityWarning;
716	    }
717	
718	    public void setCapacityWarning(Boolean capacityWarning) {
719	        this.capacityWarning = capacityWarning;
720	    }
721	
722	    public Boolean getPossibleDuplicate() {
723	        return this.possibleDuplicate;
724	    }
