    /**
     * The owner's fiscal year, formatted {@code 'FY<YY>'} where {@code YY} is the two fiscal-year
     * digits of the owner's {@link #getMemberId() member id} (its {@code FY} segment, the two
     * characters following the leading region). The fiscal year starts on 1 July and is named by the
     * calendar year in which it ends, so a registration date on or after 1 July belongs to the
     * following calendar year's fiscal year (e.g. {@code 2026-07-01} is {@code 'FY27'}) while an
     * earlier date stays in the current one (e.g. {@code 2026-06-15} is {@code 'FY26'}). Before the
     * member id has been assigned it falls back to the fiscal year of the
     * {@link #getRegistrationDate() business-day-adjusted registration date}. Returns {@code null}
     * when neither a member id nor a registration date is available.
     *
     * @return the fiscal year, or {@code null} when it cannot be derived
     */
    public String getFiscalYear() {
        if (this.memberId != null) {
            String region = leadingRegion(this.memberId);
            if (this.memberId.length() >= region.length() + 2) {
                return "FY" + this.memberId.substring(region.length(), region.length() + 2);
            }
        }
        if (this.registrationDate == null) {
            return null;
        }
        return String.format("FY%02d", fiscalYearOf(this.registrationDate) % 100);
    }

    /**
     * The fiscal year a date falls in, as a full calendar year. The fiscal year starts on 1 July and
     * is named by the calendar year in which it ends: a date in July through December belongs to the
     * next calendar year's fiscal year, while January through June stays in the current one.
     *
     * @param date the date to classify
     * @return the fiscal year as a four-digit calendar year
     */
    private static int fiscalYearOf(LocalDate date) {
        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
    }

    /**
     * The single Luhn check digit (0-9) computed over the digits contained in the given value.
     * Non-digit characters (such as the letter region and hex characters) are ignored. This is the
     * {@code CHK} segment of the {@link #getMemberId() member id}, computed over the digits of its
     * {@code <REGION><FY><HASH8>} prefix.
     *
     * @param value the value whose digits the check digit is computed over
     * @return the Luhn check digit
     */
    private static int luhnCheckDigit(String value) {
        int sum = 0;
        boolean dbl = true;
        for (int i = value.length() - 1; i >= 0; i--) {
            char c = value.charAt(i);
            if (c < '0' || c > '9') {
                continue;
            }
            int d = c - '0';
            if (dbl) {
                d *= 2;
                if (d > 9) {
                    d -= 9;
                }
            }
            sum += d;
            dbl = !dbl;
        }
        return (10 - (sum % 10)) % 10;
    }

    /**
     * The owner's membership points, the score the {@link #getMembershipLevel() membership level} is
     * derived from. The score starts at 0 and gains: 2 when an email address is present, 1 when the
     * owner has no namesakes ({@code namesakeCount} is 0), 2 for a household of 3 or more members
     * ({@code householdSize} is at least 3), and 3 when the owner's tenure spans at least one elapsed
     * fiscal year (see {@link #getTenureFiscalYears()}). Because a newly created owner has zero
     * tenure, the tenure points are never awarded at create time.
     *
     * @return the membership points, a non-negative integer
     */
    public Integer getMembershipPoints() {
        int points = 0;
        boolean hasEmail = this.email != null && !this.email.isBlank();
        if (hasEmail) {
            points += 2;
        }
        boolean hasNoNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
        if (hasNoNamesakes) {
            points += 1;
        }
        if (this.householdSize != null && this.householdSize >= 3) {
            points += 2;
        }
        Long tenureFiscalYears = getTenureFiscalYears();
        if (tenureFiscalYears != null && tenureFiscalYears >= 1) {
            points += 3;
        }
        return points;
    }

    /**
     * The owner's numeric membership level. This is normally derived from the
     * {@link #getMembershipPoints() membership points} (see {@link #deriveMembershipLevel()}), but a
     * household-level cap applied at create time may store a lower value here; when such a capped level
     * has been stored it is returned in preference to the derived one.
     *
     * @return the membership level, an integer from 1 to 4
     */
    public Integer getMembershipLevel() {
        if (this.membershipLevel != null) {
            return this.membershipLevel;
        }
        return deriveMembershipLevel();
    }

    public void setMembershipLevel(Integer membershipLevel) {
        this.membershipLevel = membershipLevel;
    }

    /**
     * The owner's numeric membership level derived purely from the {@link #getMembershipPoints()
     * membership points}: level 1 for 0-1 points, level 2 for 2-3 points, level 3 for 4-5 points, and
     * level 4 for 6 or more points. This is the uncapped level, before any household-level cap.
     *
     * @return the derived membership level, an integer from 1 to 4
     */
    public Integer deriveMembershipLevel() {
        int points = getMembershipPoints();
        if (points <= 1) {
            return 1;
        }
        if (points <= 3) {
            return 2;
        }
        if (points <= 5) {
            return 3;
        }
        return 4;
    }

    /**
     * The owner's tenure in elapsed fiscal years, the number of fiscal-year boundaries crossed from
     * the {@link #getFiscalYear() fiscal year} of the {@link #getRegistrationDate() registration date}
     * to the fiscal year of the server's current date (the fiscal year starts on 1 July). An owner
     * registered in the current fiscal year has a tenure of 0; one elapsed fiscal year or more is what
     * awards the tenure membership points. Returns {@code null} when no registration date has been set
     * yet.
     *
     * @return the tenure in elapsed fiscal years, or {@code null} when the registration date is absent
     */
    public Long getTenureFiscalYears() {
        if (this.registrationDate == null) {
            return null;
        }
        return (long) (fiscalYearOf(LocalDate.now()) - fiscalYearOf(this.registrationDate));
    }

    /**
     * The owner's locality, the canonical region string. Once the owner has a
     * {@link #getMemberId() member id} the locality is the {@code <REGION>} component of that id (its
     * leading run of letters, before the fiscal-year digits), so the locality and the identity share a
     * single source of truth. Before the member id is assigned (for example while a create is still
     * validating the postcode) it falls back to the region the id will be built from: the
     * {@link #getPostcode() postcode} looked up by range first (NSW 2000-2099, VIC 3000-3099,
     * QLD 4000-4099), then the fixed city-to-region table (Sydney->NSW, Melbourne->VIC,
     * Brisbane->QLD), and finally {@code 'UNKNOWN'} when neither resolves to a region.
     *
     * @return the canonical region string, or {@code 'UNKNOWN'}
     */
    public String getLocality() {
        if (this.memberId != null) {
            return leadingRegion(this.memberId);
        }
        return deriveRegion();
    }

    /**
     * The leading region component of a {@link #getMemberId() member id}: its leading run of letters,
     * which ends at the first fiscal-year digit. The member id has no separators, so the region is the
     * alphabetic prefix (e.g. {@code 'NSW'} or {@code 'UNKNOWN'}) that precedes the {@code <FY>} digits.
     *
     * @param memberId the member id to read the region from
     * @return the leading region string
     */
    private static String leadingRegion(String memberId) {
        int end = 0;
        while (end < memberId.length() && Character.isLetter(memberId.charAt(end))) {
            end++;
        }
        return memberId.substring(0, end);
    }

    /**
     * The owner's IANA timezone name, derived from the owner's {@link #getLocality() locality} via the
     * fixed region-to-timezone table: NSW->Australia/Sydney, VIC->Australia/Melbourne,
     * QLD->Australia/Brisbane. Returns {@code null} when the locality is not one of these regions (for
     * example the {@code 'UNKNOWN'} locality of a city with no known region).
     *
     * @return the IANA timezone name, or {@code null} when the locality has no mapped timezone
     */
    public String getTimezone() {
        return REGION_TIMEZONE.get(getLocality());
    }

    /**
     * The owner's segment, formatted {@code '<TIER>_<AREA>'}, one of {@code 'PREMIUM_METRO'},
     * {@code 'PREMIUM_REGIONAL'}, {@code 'STANDARD_METRO'} or {@code 'STANDARD_REGIONAL'}. {@code TIER}
     * is {@code 'PREMIUM'} when the {@link #getMembershipLevel() membership level} is 3 or more,
     * otherwise {@code 'STANDARD'}. {@code AREA} is {@code 'METRO'} when the {@link #getLocality()
     * locality} is a known region (NSW, VIC or QLD), otherwise {@code 'REGIONAL'}.
     *
     * @return the owner segment string
     */
    public String getOwnerSegment() {
        String tier = getMembershipLevel() >= 3 ? "PREMIUM" : "STANDARD";
        String area = REGION_TIMEZONE.containsKey(getLocality()) ? "METRO" : "REGIONAL";
        return tier + "_" + area;
    }

    /**
     * The region the customer code's {@code <REGION>} component is built from: the postcode looked up
     * by range first (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), falling back to the fixed
     * city-to-region table (Sydney->NSW, Melbourne->VIC, Brisbane->QLD) when the postcode is absent or
     * in no known range, and {@code 'UNKNOWN'} when neither resolves. Preferring the postcode returns
     * the same region for known cities but disambiguates cities that share a name.
     *
     * @return the canonical region string, or {@code 'UNKNOWN'}
     */
    private String deriveRegion() {
        String region = regionFromPostcode();
        if (region != null) {
            return region;
        }
        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
    }

    /**
     * Builds this owner's member id, formatted {@code '<REGION><FY><HASH8><CHK>'}. {@code REGION} is
     * the region derived from the postcode (falling back to the city, then {@code 'UNKNOWN'}; see
     * {@link #deriveRegion()}); {@code FY} is the two-digit fiscal year of the
     * {@link #getRegistrationDate() registration date} (the fiscal year starts on 1 July; see
     * {@link #fiscalYearOf(LocalDate)}); {@code HASH8} is the first 8 upper-case hexadecimal
     * characters of the SHA-256 digest of the owner's normalized telephone concatenated with its last
     * name (the same hash the region-and-hash identity uses); and {@code CHK} is a single Luhn check
     * digit over the digits of the {@code <REGION><FY><HASH8>} prefix (e.g. {@code 'NSW261A2B3C4D7'}).
     * It carries no sequence number, so it is a pure function of the owner's region, fiscal year,
     * telephone and last name. Call this once at create time and store the result via
     * {@link #setMemberId(String)}, which thereafter backs {@link #getLocality()} and
     * {@link #getFiscalYear()}.
     *
     * @return the assembled member id
     */
    public String buildMemberId() {
        String base = deriveRegion()
            + String.format("%02d", fiscalYearOf(this.registrationDate) % 100)
            + sha256Hex8(this.telephone + this.getLastName());
        return base + luhnCheckDigit(base);
    }

    /**
     * Computes the first 8 upper-case hexadecimal characters (the first 4 bytes) of the SHA-256 digest
     * of the given value's UTF-8 bytes, the {@code HASH8} component of the customer code.
     *
     * @param value the value to hash
     * @return the 8-character upper-case hex prefix of the SHA-256 digest
     */
    private static String sha256Hex8(String value) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256")
                .digest(value.getBytes(StandardCharsets.UTF_8));
            StringBuilder hex = new StringBuilder(8);
            for (int i = 0; i < 4; i++) {
                hex.append(String.format("%02X", digest[i]));
            }
            return hex.toString();
        }
        catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("SHA-256 algorithm not available", e);
        }
    }

    /**
     * The region whose range contains this owner's postcode, or {@code null} when the postcode is
     * absent, not a 4-digit number, or in no known range.
     *
     * @return the matching region, or {@code null}
     */
    private String regionFromPostcode() {
        if (this.postcode == null) {
            return null;
        }
        int value;
        try {
            value = Integer.parseInt(this.postcode.trim());
        }
        catch (NumberFormatException ex) {
            return null;
        }
        for (Map.Entry<String, int[]> entry : REGION_POSTCODE.entrySet()) {
            int[] range = entry.getValue();
            if (value >= range[0] && value <= range[1]) {
                return entry.getKey();
            }
        }
        return null;
    }

    /**
     * The owner's preferred contact channel, derived from the owner's details. Returns
     * {@code 'EMAIL'} when an email address is present, otherwise {@code 'PHONE'}.
     *
     * @return {@code 'EMAIL'} when an email address is present, otherwise {@code 'PHONE'}
     */
    public String getContactPreference() {
        boolean hasEmail = this.email != null && !this.email.isBlank();
        return hasEmail ? "EMAIL" : "PHONE";
    }

    /**
     * The owner's identity key, the single derived value used for duplicate detection. It is the
     * lower-case SHA-256 hex digest (64 characters) of the owner's normalized telephone, lower-cased
     * email (empty when absent) and the {@linkplain Soundex#encode(String) Soundex} of its last name,
     * joined with {@code '|'} ({@code sha256hex('<telephone>|<lowerEmail>|<soundex(lastName)>')}); any
     * absent ({@code null}) component contributes an empty string before hashing. Two owners are
     * duplicates exactly when their whole identity keys are equal, so two owners sharing a last name
     * (and its Soundex) and postcode but carrying different telephones differ here and are both
     * allowed (the second is flagged a soft match rather than rejected).
     *
     * @return the derived identity key, a 64-character lower-case hex string
     */
    public String getIdentityKey() {
        String normalizedTelephone = this.telephone == null ? "" : this.telephone;
        String lowerEmail = this.email == null ? "" : this.email.toLowerCase(Locale.ROOT);
        String raw = normalizedTelephone + "|" + lowerEmail + "|" + Soundex.encode(this.getLastName());
        return sha256HexLower(raw);
    }

    /**
     * The full lower-case SHA-256 hex digest (64 characters) of the given value's UTF-8 bytes, the
     * form the {@linkplain #getIdentityKey() identity key} takes.
     *
     * @param value the value to hash
     * @return the 64-character lower-case hex SHA-256 digest
     */
    private static String sha256HexLower(String value) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256")
                .digest(value.getBytes(StandardCharsets.UTF_8));
            StringBuilder hex = new StringBuilder(digest.length * 2);
            for (byte b : digest) {
                hex.append(String.format("%02x", b));
            }
            return hex.toString();
        }
        catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("SHA-256 algorithm not available", e);
        }
    }

